def evaluate(current_reputation, observation, my_history, round_num):
    # Use a dynamic update that depends on current reputation.
    if observation['action'] == 'cooperate':
        # Increase reputation more when it's low, less when already high
        if current_reputation >= 0:
            increment = 0.2 * (1 - current_reputation)
        else:
            increment = 0.2 * (1 + abs(current_reputation))  # boost when negative
        # Later rounds: be slightly more forgiving (smaller increment)
        if round_num > 20:
            increment *= 0.8
        return min(1.0, current_reputation + increment)
    else:  # defect
        # Decrease reputation more when it's high, less when already low
        if current_reputation <= 0:
            decrement = 0.3 * (1 + current_reputation)
        else:
            decrement = 0.3 * (1 + abs(current_reputation))
        # Later rounds: be less harsh on defection
        if round_num > 20:
            decrement *= 0.7
        return max(-1.0, current_reputation - decrement)

def decide(recipient_reputation, round_num, my_history):
    # Compute own cooperation ratio from personal history (indirect signal)
    if len(my_history) > 0:
        coop_ratio = sum(my_history) / len(my_history)
    else:
        coop_ratio = 0.5  # neutral start
    # Base threshold: more cooperative agents are more trusting
    base_threshold = 0.5 - 0.25 * coop_ratio
    # Adjust threshold downwards as rounds progress (more trusting over time)
    time_factor = 1 - 0.5 * min(1.0, round_num / 30)
    threshold = base_threshold * time_factor
    return recipient_reputation > threshold

